// What compare_exchange does, as ONE indivisible operation:
fn compare_exchange(&self, expected: u32, new: u32) -> Result<u32, u32> {
    let v = self.load();
    if v == expected {
        self.store(new);
        Ok(v)      // success: v is the old value (== expected)
    } else {
        Err(v)     // failure: nothing written, here is what was there
    }
}

fn increment(a: &AtomicU32) {
    let mut current = a.load(Relaxed);
    loop {
        let new = current + 1;
        match a.compare_exchange(current, new, Relaxed, Relaxed) {
            Ok(_) => return,
            Err(v) => current = v,
        }
    }
}

fn allocate_new_id() -> u32 {
    static NEXT_ID: AtomicU32 = AtomicU32::new(0);
    let mut id = NEXT_ID.load(Relaxed);
    loop {
        assert!(id < 1000, "too many IDs!");
        match NEXT_ID.compare_exchange_weak(id, id + 1, Relaxed, Relaxed) {
            Ok(_) => return id,
            Err(v) => id = v,
        }
    }
}

